import React from 'react';
import { names } from '../../data';

function Tips({ range, tips, shifts, onBackBtnClick, onCalculateBtnClick, onTipsChange, onShiftsChange }) {
    return (
        <div>
            <div>
                <h3>Enter tips</h3>
            </div>
            <div className='table-container'>
                <table className='table'>
                    <thead>
                        <tr>
                            <th></th>
                            <th>Morning Tip</th>
                            <th>Evening Tip</th>
                        </tr>
                    </thead>
                </table>
            </div>
        </div>
    );
}

export default Tips;
